engine.speedCheckAnalyze:
function speedCheckAnalyze(input) {
  input = input || {};
  var marks = input.marks || {};
  var tm = input.timings || null;
  var full = !!(tm && Array.isArray(tm.entries));
  var SELF = "speed_check";
  // The selection test's own Word reads are labelled "speed_check:…" — left
  // out even when the user went Home mid-test.
  var entries = (full ? tm.entries : []).filter(function (e) {
    return e && e.tool !== SELF && !(e.kind === "tool_load" && e.label === SELF) &&
      String(e.label || "").indexOf(SELF + ":") !== 0;
  }).map(copy);
  function copy(e) { var c = {}; for (var k in e) c[k] = e[k]; return c; }
  // Some catalog titles are all caps; show them in title case.
  function nice(n) {
    n = String(n || "");
    return n && n === n.toUpperCase() ? n.toLowerCase().replace(/\b\w/g, function (c) { return c.toUpperCase(); }) : n;
  }
  var names = {};
  Object.keys(input.names || {}).forEach(function (id) { names[id] = nice(input.names[id]); });
  // Names the kernel stamped on opens/loads fill in tools no longer loaded.
  entries.forEach(function (e) {
    if (e.name && (e.kind === "tool_open" || e.kind === "tool_load") && !names[e.label]) names[e.label] = nice(e.name);
  });

  // Status bands (ms). Word's is the kernel's hard 100ms Word.run budget.
  var BAND = {
    startup: [600, 1500], open: [300, 1000], load: [100, 300],
    storage: [200, 1000], word: [100, 1000],
  };
  function status(ms, band) {
    if (ms == null) return "info";
    return ms < band[0] ? "ok" : (ms < band[1] ? "warn" : "bad");
  }
  var RANK = { bad: 3, warn: 2, ok: 1, info: 0 };
  function worse(a, b) { return RANK[a] >= RANK[b] ? a : b; }

  function sec(ms) {
    if (ms == null) return "–";
    if (ms < 50) return "<0.1s";
    if (ms < 10000) return (ms / 1000).toFixed(1) + "s";
    return Math.round(ms / 1000) + "s";
  }
  function words(n) {
    return ["no", "One", "Two", "Three", "Four", "Five"][n] || String(n);
  }
  function pretty(s) {
    return String(s || "").replace(/^app_/, "").replace(/^host[:.]/, "")
      .replace(/[_:.\-]+/g, " ").replace(/\s+/g, " ").trim();
  }
  function cap(s) { s = String(s || ""); return s.charAt(0).toUpperCase() + s.slice(1); }
  function toolName(id) {
    if (id === "_home") return "Home";
    if (!id) return "ELI";
    return names[id] || pretty(id).replace(/\b\w/g, function (c) { return c.toUpperCase(); });
  }
  function max(list, f) { var m = null; list.forEach(function (x) { var v = f(x); if (v != null && (m == null || v > m)) m = v; }); return m; }
  function sum(list, f) { var s = 0; list.forEach(function (x) { s += f(x) || 0; }); return s; }
  function groupBy(list, keyFn) {
    var out = {}, order = [];
    list.forEach(function (x) {
      var k = keyFn(x);
      if (!out[k]) { out[k] = []; order.push(k); }
      out[k].push(x);
    });
    return order.map(function (k) { return { key: k, items: out[k] }; });
  }
  function listJoin(a) {
    return a.length < 2 ? (a[0] || "") : a.slice(0, -1).join(", ") + (a.length > 2 ? "," : "") + " and " + a[a.length - 1];
  }
  // A timing includes time spent queued: saved data and Word each work
  // through one request at a time, so one slow call makes the calls after
  // it look slow (Home's selection read sat behind its bookmark cleanup).
  // An entry "waited" when a 0.1s+ call of the same kind that started
  // first covered most of its time; it is then not reported as a problem
  // of its own — the call it waited behind is.
  var WAIT_MIN_MS = 100;
  function markWaiting(list) {
    list.forEach(function (e, ei) {
      if (e.t == null || !(e.ms > 0)) return;
      var es = e.t - e.ms, best = null;
      list.forEach(function (b, bi) {
        if (b === e || b.t == null || b.ms < WAIT_MIN_MS) return;
        var bs = b.t - b.ms;
        var first = bs < es || (bs === es && (b.ms > e.ms || (b.ms === e.ms && bi < ei)));
        if (!first) return;
        var overlap = Math.min(e.t, b.t) - Math.max(es, bs);
        if (overlap >= e.ms * 0.6 && (!best || b.ms > best.ms)) best = b;
      });
      e.behind = best;
    });
  }
  // Names of the other groups whose calls waited behind this group's long
  // enough to have looked slow themselves.
  function waitersOf(groupKey, list, keyFn, nameFn) {
    var seen = {}, names = [];
    list.forEach(function (e) {
      if (!e.behind || e.ms < WAIT_MIN_MS || keyFn(e.behind) !== groupKey || keyFn(e) === groupKey) return;
      var n = nameFn(e);
      if (!seen[n]) { seen[n] = true; names.push(n); }
    });
    return names.length > 3 ? names.slice(0, 3).concat([(names.length - 3) + " more"]) : names;
  }

  // ── Startup ────────────────────────────────────────────────────────────
  var start = marks["boot:office_ready"];
  var firstScreenAbs = marks["boot:first_paint"] != null ? marks["boot:first_paint"] : marks["boot:interactive"];
  var readyAbs = null;
  if (marks["boot:preload_ready"] != null || marks["boot:tools_ready"] != null) {
    readyAbs = Math.max(marks["boot:preload_ready"] || 0, marks["boot:tools_ready"] || 0);
  }
  // Older kernel: the end of the startup run of eli_stats' tool_loaded:*
  // stamps (each tier loads in one go; a gap over 1s is a later install).
  var oldLoads = [];
  (function () {
    var tierDone = marks["tools_boot_tier_done"];
    var rows = Object.keys(marks).filter(function (k) { return k.indexOf("tool_loaded:") === 0; })
      .map(function (k) { return { id: k.slice(12), t: marks[k] }; })
      .sort(function (a, b) { return a.t - b.t; });
    if (!rows.length) return;
    function spans(a, b) { return tierDone != null && a.t <= tierDone && tierDone <= b.t; }
    var run = [rows[0]];
    for (var i = 1; i < rows.length; i++) {
      if (rows[i].t - rows[i - 1].t > 1000 && !spans(rows[i - 1], rows[i])) break;
      run.push(rows[i]);
    }
    for (var j = 1; j < run.length; j++) {
      if (!spans(run[j - 1], run[j])) oldLoads.push({ id: run[j].id, ms: Math.round(run[j].t - run[j - 1].t) });
    }
    if (readyAbs == null) readyAbs = run[run.length - 1].t;
  })();
  var startupMs = (start != null && readyAbs != null) ? Math.max(0, Math.round(readyAbs - start))
    : (start != null && marks["boot:interactive"] != null ? Math.round(marks["boot:interactive"] - start) : null);
  var firstScreenMs = (start != null && firstScreenAbs != null) ? Math.max(0, Math.round(firstScreenAbs - start)) : null;
  var startupEnd = readyAbs != null ? readyAbs : (marks["boot:interactive"] != null ? marks["boot:interactive"] : null);
  // Word/storage work that ran during startup, not inside a tool.
  function atStartup(e) {
    return !e.tool && startupEnd != null && e.t != null && e.t <= startupEnd + 1500;
  }
  var loads = full
    ? entries.filter(function (e) { return e.kind === "tool_load" && startupEnd != null && e.t <= startupEnd + 200; })
        .map(function (e) { return { id: e.label, ms: e.ms }; })
    : oldLoads;
  loads.sort(function (a, b) { return b.ms - a.ms; });

  // ── Where a timing happened, in words ─────────────────────────────────
  // A Word step labelled "<tool>:<step>" belongs to that tool even when it
  // wasn't opened from its tile (Ask ELI from the home bar, Build Draft
  // from the OARS chip) — the kernel only knows tile launches.
  function labelTool(e) {
    if (e.kind !== "word") return null;
    var m = /^([a-z][a-z0-9_]*):/.exec(String(e.label || ""));
    return m && m[1] !== "host" ? m[1] : null;
  }
  function ctxKey(e) { return e.tool || labelTool(e) || e.inferredTool || (atStartup(e) ? "_startup" : ""); }
  function where(key) {
    if (key === "_home") return "when you press Home";
    if (key === "_startup") return "at startup";
    if (!key) return "on the home screen";
    return "in " + toolName(key);
  }

  // ── Word ───────────────────────────────────────────────────────────────
  var WORD = {
    readText: "reading the document",
    readTextWithAnchors: "reading the document",
    readStructuralMap: "mapping the document's sections",
    getSelection: "reading your selection",
    findRange: "finding text in the document",
    proposeEdit: "making an edit",
    highlightAnchor: "jumping to a spot in the document",
    cleanupAnchors: "cleaning up bookmarks",
    "host:applySurgicalRedline": "applying a redline",
    "host.insertImage": "inserting an image",
    raw: "working in the document",
    resilient: "working in the document",
  };
  // Tool steps that show up often, in plain words. Any other tool step
  // still reads as: the “resolve redlines” step.
  var STEPS = {
    "ask_eli:read_doc": "reading the whole document",
    "ask_eli:read_sel": "reading your selection",
    "ask_eli:read_text_only": "checking whether the document changed",
    "ask_eli:anchor_sweep": "clearing old citation bookmarks",
    "ask_eli:read_comments": "reading comments",
    "build_draft:tpl_body_combined": "inserting the template body",
    "build_draft:tpl_restore_xml": "restoring the template's hidden data",
    "build_draft:normalize_host_styles": "matching the document's styles",
    "build_draft:oars_scan": "scanning for OARS details",
    "error_review:resolve_redlines": "reading the tracked changes",
    "error_review:footers": "checking the footers",
    "error_review:index": "bookmarking each finding",
    "oars_loader:body_scan": "checking for an OARS export",
  };
  function stepWhat(label) {
    if (STEPS[label]) return STEPS[label];
    var m = /^build_draft:tpl_section_combined_(\d+)$/.exec(String(label));
    return m ? "adding headers and footers to section " + (Number(m[1]) + 1) : null;
  }
  function wordWhat(label) { return WORD[label] || stepWhat(label) || pretty(label).toLowerCase(); }
  // A tool's own Word step, labelled "<tool>:<step>" (error_review:index).
  function wordStep(label) {
    if (WORD[label] || stepWhat(label)) return null;
    var i = String(label).indexOf(":");
    return i > 0 ? pretty(String(label).slice(i + 1)).toLowerCase() : null;
  }
  function wordName(label) { return cap(wordStep(label) || wordWhat(label)); }
  function wordRef(label) { var s = wordStep(label); return s ? "the “" + s + "” step" : wordWhat(label); }
  var wordEntries = entries.filter(function (e) { return e.kind === "word"; });
  if (!full) {
    // Older kernel: each host:<label> mark pair keeps only its latest run.
    Object.keys(marks).forEach(function (k) {
      if (k.indexOf("host:") !== 0 || k.slice(-6) !== ":start") return;
      var base = k.slice(0, -6), s = marks[k], e = marks[base + ":end"];
      if (e == null || e < s) return;
      wordEntries.push({ kind: "word", label: base.slice(5), ms: Math.round(e - s), t: e, tool: null });
    });
  }
  // A Gemini call or kernel Word step made outside a tile launch (Ask ELI
  // from the home bar) is credited to the tool whose own Word step was
  // running, or ended within 3s, when it started — that tool read the
  // document and then mapped it / asked Gemini. Selection reads are the
  // shared selection watcher's, never a tool's.
  var INFER_MS = 3000;
  function inferTool(a) {
    if (a.tool || a.t == null || labelTool(a) || atStartup(a) || (a.kind === "word" && a.label === "getSelection")) return;
    var start = a.t - a.ms, best = null;
    wordEntries.forEach(function (w) {
      var tool = w.tool || labelTool(w);
      if (w === a || !tool || tool.charAt(0) === "_" || w.t == null) return;
      var running = w.t - w.ms <= start && w.t >= start;
      var justBefore = w.t <= start + 50 && start - w.t <= INFER_MS;
      if (!(running || justBefore)) return;
      if (!best || w.t > best.t) best = { t: w.t, tool: tool };
    });
    if (best) a.inferredTool = best.tool;
  }
  wordEntries.forEach(inferTool);
  markWaiting(wordEntries);
  function wordKey(e) { return e.label + "|" + ctxKey(e); }
  function byOwn(a, b) { return (b.ownMax - a.ownMax) || (b.max - a.max); }
  var wordGroups = groupBy(wordEntries, wordKey).map(function (g) {
    var e0 = g.items[0];
    var worst = g.items.slice().sort(function (a, b) { return b.ms - a.ms; })[0];
    var own = g.items.filter(function (e) { return !e.behind; });
    return {
      key: g.key, label: e0.label, ctx: ctxKey(e0), count: g.items.length,
      slow: own.filter(function (e) { return e.ms > BAND.word[0]; }).length,
      max: worst.ms, ownMax: own.length ? max(own, function (e) { return e.ms; }) : 0,
      behind: worst.behind || null,
      waited: g.items.length - own.length,
      inferred: g.items.some(function (e) { return !!e.inferredTool; }),
      avg: Math.round(sum(g.items, function (e) { return e.ms; }) / g.items.length),
      // A step that fails after seconds otherwise reads like a slow success.
      failed: g.items.filter(function (e) { return e.ok === false; }).length,
    };
  }).sort(byOwn);
  var slowWord = wordEntries.filter(function (e) { return !e.behind && e.ms > BAND.word[0]; });
  var wordTop = wordGroups[0] || null;

  // ── Opening tools ──────────────────────────────────────────────────────
  function ready(e) { return e.settleMs != null ? Math.max(e.ms, e.settleMs) : e.ms; }
  var opens = entries.filter(function (e) { return e.kind === "tool_open"; });
  var openGroups = groupBy(opens, function (e) { return e.label; }).map(function (g) {
    var worst = g.items.slice().sort(function (a, b) { return ready(b) - ready(a); })[0];
    var later = g.items.filter(function (e) { return !e.firstLoad; });
    return {
      id: g.key, name: toolName(g.key), count: g.items.length,
      ms: ready(worst), paint: worst.ms, firstLoad: !!worst.firstLoad,
      laterMax: later.length ? max(later, ready) : null,
    };
  });
  var homes = entries.filter(function (e) { return e.kind === "home"; });
  if (homes.length) {
    openGroups.push({ id: "_home", name: "Home screen", count: homes.length, ms: max(homes, function (e) { return e.ms; }), paint: null, firstLoad: false, laterMax: null });
  }
  openGroups.sort(function (a, b) { return b.ms - a.ms; });
  var openTop = openGroups.filter(function (g) { return g.id !== "_home"; })[0] || openGroups[0] || null;

  // ── Gemini ─────────────────────────────────────────────────────────────
  var ais = entries.filter(function (e) { return e.kind === "ai" && !e.cancelled; });
  ais.forEach(inferTool);
  var aiDone = ais.filter(function (e) { return e.ok !== false; });
  var aiGroups = groupBy(aiDone, function (e) { return e.tool || e.inferredTool || ""; }).map(function (g) {
    var firsts = g.items.filter(function (e) { return e.firstMs != null; });
    return {
      inferred: g.items.some(function (e) { return !e.tool && e.inferredTool; }),
      id: g.key, name: g.key ? toolName(g.key) : "In the background", count: g.items.length,
      avg: Math.round(sum(g.items, function (e) { return e.ms; }) / g.items.length),
      max: max(g.items, function (e) { return e.ms; }),
      first: firsts.length ? Math.round(sum(firsts, function (e) { return e.firstMs; }) / firsts.length) : null,
      models: groupBy(g.items, function (e) { return e.label; }).map(function (m) { return m.key; }),
    };
  }).sort(function (a, b) { return b.avg - a.avg; });
  var retries = entries.filter(function (e) { return e.kind === "ai_retry"; });
  var aiFailed = ais.filter(function (e) { return e.ok === false; });

  // ── Saved data ─────────────────────────────────────────────────────────
  var STORES = {
    templates: "saved templates", bd_templates: "Build Draft templates", bd_clauses: "the clause library",
    playbooks: "playbooks", team_commentary: "team guidance", risk_rules: "risk rules",
    json_tools: "installed tools", config: "settings", stats: "usage stats", trophies: "trophies",
    catalog: "the tool list", prompts: "AI prompts", email_templates: "email templates",
    agreement_types: "agreement types", requesters: "saved requesters", loading_msgs: "loading messages",
    cleaner_rules: "cleanup rules", exec_brief_terms: "brief terms", wrongness_captures: "debug captures",
  };
  function storeName(s) { return STORES[s] || pretty(s).toLowerCase(); }
  var reads = entries.filter(function (e) { return e.kind === "storage"; });
  markWaiting(reads);
  var WRITE_OPS = { put: true, putMany: true, "delete": true, clearStore: true };
  function storeKey(e) { return e.label + "|" + ctxKey(e); }
  var storeGroups = groupBy(reads, storeKey).map(function (g) {
    var e0 = g.items[0];
    var worst = g.items.slice().sort(function (a, b) { return b.ms - a.ms; })[0];
    var own = g.items.filter(function (e) { return !e.behind; });
    return {
      key: g.key, store: e0.label, ctx: ctxKey(e0), count: g.items.length,
      writes: g.items.filter(function (e) { return WRITE_OPS[e.op]; }).length,
      max: worst.ms, ownMax: own.length ? max(own, function (e) { return e.ms; }) : 0,
      rows: max(g.items, function (e) { return e.rows; }), behind: worst.behind || null,
      waited: g.items.length - own.length,
    };
  }).sort(byOwn);
  var storeTop = storeGroups[0] || null;
  function storeVerb(g) { return g.writes === g.count ? "Saving" : (g.writes ? "Reading and saving" : "Reading"); }
  function blockerName(b) { return b.kind === "storage" ? storeName(b.label) : wordRef(b.label); }
  // Bar colour: a row slow only from waiting is coloured by its own time.
  function rowStatus(g, band) { return status(g.behind && g.ownMax < g.max ? g.ownMax : g.max, band); }

  // ── Cards ──────────────────────────────────────────────────────────────
  // A row may carry its own value text (a size, a count) and no bar.
  function bars(rows) {
    var top = max(rows.filter(function (r) { return !r.noBar; }), function (r) { return r.ms; }) || 1;
    return rows.map(function (r) {
      r.pct = r.noBar ? 0 : Math.max(3, Math.round((r.ms / top) * 100));
      r.time = r.text != null ? r.text : sec(r.ms);
      return r;
    });
  }
  function mb(chars) {
    if (chars == null) return "–";
    var m = chars / 1048576;
    if (m >= 1024) return (m / 1024).toFixed(1) + " GB";
    return (m >= 10 ? Math.round(m) : m.toFixed(1)) + " MB";
  }
  function median(a) {
    if (!a || !a.length) return null;
    var s = a.slice().sort(function (x, y) { return x - y; });
    return s[Math.floor(s.length / 2)];
  }
  // Live facts gathered by init: memory, tool code sizes, saved data,
  // screen elements, freeze-recorder support, and three quick Word trips.
  var sys = input.system || null;
  var trips = sys && sys.wordTrips;
  var tripMed = median(trips);
  var TRIP_BAND = [100, 300];
  var cards = [];
  var startupStatus = status(startupMs, BAND.startup);
  cards.push({
    key: "startup", name: "Starting up", status: startupStatus,
    value: sec(startupMs), unit: "",
    note: startupMs == null ? "Not recorded"
      : (startupStatus === "ok" ? "Fast · target under 0.6s" : "Target under 0.6s"),
    rows: bars([].concat(
      firstScreenMs != null ? [{ name: "First screen", ms: firstScreenMs, status: status(firstScreenMs, BAND.startup) }] : [],
      startupMs != null ? [{ name: "All tools ready", ms: startupMs, status: startupStatus }] : [],
      loads.slice(0, 4).map(function (l) { return { name: toolName(l.id), sub: "loading", ms: l.ms, status: status(l.ms, BAND.load) }; })
    )),
    target: "From when Word hands ELI the panel. Green under 0.6s · amber under 1.5s.",
  });

  var wordStatus = !wordEntries.length ? "info" : status(wordTop ? wordTop.ownMax : 0, BAND.word);
  cards.push({
    key: "word", name: "Talking to Word", status: wordStatus,
    value: !wordEntries.length ? "–" : (slowWord.length ? String(slowWord.length) : "All quick"),
    unit: slowWord.length ? (slowWord.length === 1 ? "slow moment" : "slow moments") : "",
    note: !wordEntries.length ? (tripMed != null ? "Right now a quick trip takes " + sec(tripMed) : "Nothing yet")
      : (slowWord.length ? "Longest " + sec(wordTop.ownMax) + ", " + where(wordTop.ctx)
        : "Every trip to Word under 0.1s"),
    rows: bars([].concat(
      tripMed != null ? [{ name: "Quick check right now", sub: trips.length + " trips while ELI is idle", ms: tripMed, status: status(tripMed, TRIP_BAND) }] : [],
      wordGroups.slice(0, 6).map(function (g) {
        return {
          name: wordName(g.label), ms: g.max, status: rowStatus(g, BAND.word),
          sub: where(g.ctx) + (g.count > 1 ? " · " + g.count + "×" : "") + (g.behind ? " · waiting behind " + blockerName(g.behind) : ""),
        };
      }))),
    target: "Each trip to Word should take under 0.1s; ELI waits while Word works.",
  });

  var openStatus = !openGroups.length ? "info" : status(openGroups[0].ms, BAND.open);
  var quick = openGroups.filter(function (g) { return g.ms < BAND.open[0]; }).length;
  cards.push({
    key: "open", name: "Opening tools", status: !full ? "info" : openStatus,
    value: !full || !openTop ? "–" : sec(openTop.ms),
    unit: openTop && full ? "slowest: " + openTop.name : "",
    note: !full ? "Needs the ELI OS update"
      : (!openGroups.length ? "Open a few tools first"
        : (quick === openGroups.length ? "Every tool opens in under 0.3s."
          : (quick * 2 >= openGroups.length ? "Most tools open in under 0.3s." : quick + " of " + openGroups.length + " open in under 0.3s."))),
    rows: bars(openGroups.slice(0, 8).map(function (g) {
      var sub = [];
      if (g.firstLoad) sub.push("first open");
      if (g.paint != null && g.ms - g.paint > 300) sub.push("shows at " + sec(g.paint));
      return { name: g.name, sub: sub.join(" · "), ms: g.ms, status: status(g.ms, BAND.open) };
    })),
    target: "From your click until the tool has filled in. Green under 0.3s · amber under 1s · red over 1s.",
  });

  var aiTop = aiGroups[0] || null;
  cards.push({
    key: "ai", name: "Waiting for Gemini", status: "info",
    value: !full || !aiTop ? "–" : sec(aiTop.avg), unit: aiTop && full ? aiTop.name : "",
    note: !full ? "Needs the ELI OS update"
      : (!aiTop ? "No AI calls yet"
        : (aiGroups[1] ? aiGroups[1].name + " " + sec(aiGroups[1].avg) + " · that's Gemini's time" : "That's Gemini's time, not ELI's")),
    rows: bars(aiGroups.slice(0, 6).map(function (g) {
      return {
        name: g.name, ms: g.avg, status: "info",
        sub: g.count + (g.count === 1 ? " call" : " calls") + (g.first != null ? " · first words " + sec(g.first) : ""),
      };
    })),
    target: "Average time for Gemini's full answer. Gemini decides this — the model and how much it reads.",
  });

  cards.push({
    key: "storage", name: "Loading saved data", status: !full ? "info" : (!storeTop ? "info" : status(storeTop.ownMax, BAND.storage)),
    value: !full || !storeTop ? "–" : sec(storeTop.ownMax),
    unit: "",
    note: !full ? "Needs the ELI OS update"
      : (!storeTop ? "Nothing read yet" : cap(storeName(storeTop.store)) + ", " + where(storeTop.ctx)),
    rows: bars(storeGroups.slice(0, 6).map(function (g) {
      return {
        name: cap(storeName(g.store)), ms: g.max, status: rowStatus(g, BAND.storage),
        sub: where(g.ctx) + (g.rows != null ? " · " + g.rows + " items" : "") + (g.count > 1 ? " · " + g.count + "×" : "") +
          (g.behind ? " · waiting behind " + blockerName(g.behind) : ""),
      };
    })),
    target: "Reading and saving ELI's data on this computer. Green under 0.2s · amber under 1s.",
  });

  // Freezes: stretches the panel itself couldn't respond (kernel [FREEZES]).
  var FREEZE_BAND = [200, 1000];
  var freezes = entries.filter(function (e) { return e.kind === "freeze"; });
  var freezeSupport = sys ? sys.freezes : "old-kernel";
  var freezeGroups = groupBy(freezes, ctxKey).map(function (g) {
    return { ctx: ctxKey(g.items[0]), count: g.items.length, max: max(g.items, function (e) { return e.ms; }) };
  }).sort(function (a, b) { return b.max - a.max; });
  var freezeTop = freezeGroups[0] || null;
  cards.push({
    key: "freeze", name: "Freezes",
    status: freezeSupport !== "yes" ? "info" : (freezeTop ? status(freezeTop.max, FREEZE_BAND) : "ok"),
    value: freezeSupport !== "yes" ? "–" : (freezes.length ? String(freezes.length) : "None"),
    unit: freezes.length ? (freezes.length === 1 ? "freeze" : "freezes") : "",
    note: freezeSupport === "old-kernel" ? "Needs the ELI OS update"
      : freezeSupport === "unsupported" ? "Not available in this version of Word"
        : (freezeTop ? "Longest " + sec(freezeTop.max) + ", " + where(freezeTop.ctx) : "ELI's panel never got stuck"),
    rows: bars(freezeGroups.slice(0, 6).map(function (g) {
      return { name: cap(where(g.ctx)), sub: g.count > 1 ? g.count + " freezes" : "1 freeze", ms: g.max, status: status(g.max, FREEZE_BAND) };
    })),
    target: "Times ELI's own panel couldn't respond for 0.2s or more — clicks and typing wait. Not Word, not Gemini.",
  });

  // Memory and size — information, not a speed score.
  var code = sys && sys.code;
  var codeAll = code ? code.loaded + code.waiting : null;
  var DOM_HIGH = 8000;
  var memRows = [];
  if (sys && sys.heap) memRows.push({ name: "ELI's panel", text: mb(sys.heap.used), sub: "memory in use", noBar: true, ms: 0, status: "info" });
  if (code) memRows.push({ name: "Tool code held", text: mb(codeAll), noBar: true, ms: 0, status: "info",
    sub: (code.loadedN + code.waitingN) + " tools · " + mb(code.waiting) + " for " + code.waitingN + " not opened yet" });
  if (sys && sys.storage) memRows.push({ name: "Saved data", text: mb(sys.storage.used), sub: "of " + mb(sys.storage.quota) + " allowed", noBar: true, ms: 0, status: "info" });
  if (sys && sys.domNodes != null) memRows.push({ name: "Screen elements", text: sys.domNodes.toLocaleString(), noBar: true, ms: 0,
    status: sys.domNodes > DOM_HIGH ? "warn" : "info", sub: sys.domNodes > DOM_HIGH ? "a lot — redraws slow down" : "fine" });
  cards.push({
    key: "memory", name: "Memory", status: sys && sys.domNodes > DOM_HIGH ? "warn" : "info",
    value: sys && sys.heap ? mb(sys.heap.used) : (code ? mb(codeAll) : "–"),
    unit: sys && sys.heap ? "in use" : (code ? "tool code" : ""),
    note: code ? "Tool code " + mb(codeAll) + " · " + mb(code.waiting) + " not opened yet" : "Not available",
    rows: bars(memRows),
    target: "What ELI's panel holds right now. Memory use isn't timed — it matters if it keeps growing or the panel gets sluggish.",
  });

  // ── Issues ─────────────────────────────────────────────────────────────
  var issues = [];
  function add(sev, ms, who, text, fix, short) {
    issues.push({ sev: sev, ms: ms, who: who, text: text, fix: fix, short: short });
  }
  var coveredStores = {};
  openGroups.forEach(function (g) {
    var st = status(g.ms, BAND.open);
    if (st === "ok") return;
    var isHome = g.id === "_home";
    var name = isHome ? "the Home screen" : g.name;
    var text = (isHome ? "Going back to the Home screen takes " : "Opening " + name + " takes ") + sec(g.ms) + ".";
    if (g.paint != null && g.ms - g.paint > 300) {
      text = "Opening " + name + " takes " + sec(g.ms) + ": it shows at " + sec(g.paint) + " and fills in by " + sec(g.ms) + ".";
    }
    var biggest = storeGroups.filter(function (s) { return s.ctx === g.id && s.ownMax >= g.ms * 0.5; })[0];
    var fix;
    if (biggest) {
      coveredStores[biggest.key] = true;
      text += " Most of that is " + storeVerb(biggest).toLowerCase() + " " + storeName(biggest.store) + " (" + sec(biggest.ownMax) +
        (biggest.rows != null ? ", " + biggest.rows + " items" : "") + ").";
      fix = "Reading less here — a small index instead of everything — would fix it.";
    } else if (g.firstLoad && (g.laterMax == null || g.laterMax < BAND.open[0])) {
      fix = g.laterMax == null ? "This was the first open, which includes loading the tool."
        : "Only the first open is slow — that's ELI loading the tool. Loading it earlier would fix it.";
    } else {
      fix = "ELI's own drawing of the tool is slow here.";
    }
    add(st, g.ms, "eli", text, fix, isHome ? "going back Home" : "opening " + g.name);
  });
  function upTo(g) { return g.count > 1 ? "up to " : ""; }
  wordGroups.forEach(function (g) {
    if (g.ownMax <= BAND.word[0]) return;
    var w = where(g.ctx), step = wordStep(g.label);
    var times = g.count < 2 ? "" : (g.slow === g.count ? " (" + g.count + " times)" : " — slow " + g.slow + " of " + g.count + " times");
    var waiters = waitersOf(g.key, wordEntries, wordKey, function (e) { return wordRef(e.label); });
    add(status(g.ownMax, BAND.word) === "bad" ? "bad" : "warn", g.ownMax, "eli",
      cap(w) + ", " + (step ? "the “" + step + "” step spends " + upTo(g) + sec(g.ownMax) + " in Word"
        : "ELI spends " + upTo(g) + sec(g.ownMax) + " " + wordWhat(g.label) + " in Word") + times + "." +
        (waiters.length ? " " + cap(listJoin(waiters)) + " had to wait behind it." : ""),
      "Fewer or smaller trips to Word would fix it.",
      step ? "“" + step + "” " + w
        : (g.ctx === "_home" ? "pressing Home" : (g.ctx === "_startup" ? "Word at startup" : wordWhat(g.label) + " " + w)));
  });
  storeGroups.forEach(function (g) {
    if (g.ownMax < 500 || coveredStores[g.key]) return;
    var waiters = waitersOf(g.key, reads, storeKey, function (e) { return storeName(e.label); });
    var verb = storeVerb(g);
    add(status(g.ownMax, BAND.storage), g.ownMax, "eli",
      verb + " " + storeName(g.store) + " takes " + upTo(g) + sec(g.ownMax) + (g.rows != null ? " (" + g.rows + " items)" : "") +
        ", " + (g.count > 1 ? g.count + " times " : "") + where(g.ctx) + "." +
        (waiters.length ? " " + cap(listJoin(waiters)) + " had to wait behind it." : ""),
      verb === "Saving" ? "Saving less often, or less at a time, would fix it." : "Reading less — an index or a summary — would fix it.",
      verb.toLowerCase() + " " + storeName(g.store));
  });
  if (startupMs != null && startupStatus !== "ok") {
    var slowLoad = loads[0] && loads[0].ms >= 150 ? loads[0] : null;
    add(startupStatus, startupMs, "eli",
      "Starting up takes " + sec(startupMs) + "." + (slowLoad ? " The slowest part is loading " + toolName(slowLoad.id) + " (" + sec(slowLoad.ms) + ")." : ""),
      slowLoad ? "That tool could load when it's first opened instead of at startup." : "Several tools load at startup; fewer would help.",
      "starting up");
  }
  aiGroups.forEach(function (g) {
    if (g.avg < 5000) return;
    add("info", g.avg, "gemini",
      (g.id ? g.name : "Background AI work") + " waits about " + sec(g.avg) + " for Gemini" + (g.count > 1 ? " each time" : "") + ".",
      "That's Gemini working. A faster model in Settings or a shorter document helps; nothing in ELI to fix.",
      g.name);
  });
  if (retries.length) {
    add("info", sum(retries, function (e) { return e.ms; }), "gemini",
      "Gemini was busy " + (retries.length === 1 ? "once" : retries.length + " times") + "; ELI waited " +
        sec(sum(retries, function (e) { return e.ms; })) + " before trying again.",
      "Google's servers were overloaded. Nothing to fix in ELI.", "Gemini busy");
  }
  if (aiFailed.length) {
    add("info", 0, "gemini",
      (aiFailed.length === 1 ? "One Gemini request" : aiFailed.length + " Gemini requests") + " failed or timed out.",
      "Usually the network or Google's servers. Copy for Claude has the details.", "Gemini failures");
  }
  // Word answering slowly while ELI is idle is Word's own state, not ELI's.
  if (tripMed != null && tripMed >= 150) {
    add(status(tripMed, [150, 500]), tripMed, "word",
      "Word is slow to answer right now: a quick trip takes " + sec(tripMed) + " (normally well under 0.1s). Every ELI step that touches the document waits on this.",
      "Usually a very long document, lots of tracked changes or comments, or Word busy (autosave, syncing). Nothing in ELI to fix.",
      "Word slow to answer");
  }
  if (freezeTop && freezeTop.max >= 500) {
    add(status(freezeTop.max, FREEZE_BAND), freezeTop.max, "eli",
      "ELI's panel froze " + (freezes.length === 1 ? "once" : freezes.length + " times") + " (longest " + sec(freezeTop.max) + "), mostly " + where(freezeTop.ctx) + ".",
      freezeTop.ctx === "_startup" ? "That's tools loading at startup; fewer or lighter startup tools would help."
        : "One long piece of work runs in a single go; splitting it up would fix it.",
      "freezes " + where(freezeTop.ctx));
  }
  if (sys && sys.domNodes > DOM_HIGH) {
    add("warn", 0, "eli",
      "ELI's panel holds " + sys.domNodes.toLocaleString() + " screen elements — redrawing that many slows things down.",
      "Usually a long chat or a big result list still on screen; clearing it helps.",
      "screen elements");
  }
  issues.sort(function (a, b) {
    if ((a.who === "eli") !== (b.who === "eli")) return a.who === "eli" ? -1 : 1;
    if (RANK[a.sev] !== RANK[b.sev]) return RANK[b.sev] - RANK[a.sev];
    return b.ms - a.ms;
  });

  // ── Verdict ────────────────────────────────────────────────────────────
  var eliIssues = issues.filter(function (i) { return i.who === "eli"; });
  var badCount = eliIssues.filter(function (i) { return i.sev === "bad"; }).length;
  var used = opens.length + ais.length + freezes.length + wordEntries.filter(function (e) { return !atStartup(e); }).length;
  var empty = full && used === 0;
  var gem = aiGroups.filter(function (g) { return g.avg >= 5000; })[0];
  var gemLine = gem ? " " + (gem.id ? gem.name + "'s" : "The background") + " wait is Gemini, not ELI." : "";
  var verdict;
  if (empty) {
    verdict = { title: "Nothing measured yet.", detail: "Use ELI for a few minutes — open some tools, ask a question — then come back." +
      (startupMs != null ? " Startup took " + sec(startupMs) + "." : "") };
  } else if (!eliIssues.length) {
    verdict = { title: "ELI is fast.", detail: "Nothing in ELI is slow." + (gem ? " The longest waits are Gemini thinking (" + gem.name + ", about " + sec(gem.avg) + ")." : "") };
  } else {
    var shorts = [];
    eliIssues.forEach(function (i) { if (shorts.length < 3 && shorts.indexOf(i.short) === -1) shorts.push(i.short); });
    var list = listJoin(shorts);
    var n = eliIssues.length;
    verdict = {
      title: (badCount >= 2 || n >= 4) ? "A few things in ELI are slow." : "ELI is mostly fast.",
      detail: (n === 1 ? "One thing is slow: " : words(n) + " things are slow" + (n > 3 ? ", mainly " : ": ")) + list + "." + gemLine,
    };
  }
  if (!full) {
    verdict.detail = (verdict.detail ? verdict.detail + " " : "") + "Update ELI OS for full timings — this one only keeps startup and Word.";
  }

  // ── Copy for Claude (ids + numbers only, never document text) ──────────
  var L = [];
  L.push("ELI Speed Check · kernel " + (input.kernelVersion || "?") + " · " + (full ? entries.length + " timings" : "marks only (old kernel)") +
    (full && tm.since ? " since " + new Date(tm.since).toISOString() : ""));
  L.push("Startup: first screen " + (firstScreenMs == null ? "?" : firstScreenMs + "ms") + ", all tools ready " + (startupMs == null ? "?" : startupMs + "ms"));
  if (loads.length) L.push("  tool loads: " + loads.slice(0, 8).map(function (l) { return l.id + " " + l.ms; }).join(", "));
  if (openGroups.length) L.push("Opens (ready/paint ms): " + openGroups.map(function (g) {
    return g.id + " " + g.ms + (g.paint != null ? "/" + g.paint : "") + (g.firstLoad ? " first" : "") + " x" + g.count + (g.laterMax != null ? " later-max " + g.laterMax : "");
  }).join("; "));
  // "own" = longest not spent waiting; "waited N" = calls queued behind a longer one.
  if (wordGroups.length) L.push("Word (label @ where[~ inferred]: n, max, own, avg[, waited][, FAILED]): " + wordGroups.slice(0, 12).map(function (g) {
    return g.label + " @ " + (g.ctx || "dashboard") + (g.inferred ? "~" : "") + ": " + g.count + ", " + g.max + ", " + g.ownMax + ", " + g.avg +
      (g.waited ? ", waited " + g.waited : "") + (g.failed ? ", FAILED " + g.failed : "");
  }).join("; "));
  var opGroups = groupBy(reads, function (e) { return storeKey(e) + "|" + e.op; }).map(function (g) {
    var e0 = g.items[0];
    return {
      store: e0.label, ctx: ctxKey(e0), op: e0.op, count: g.items.length,
      max: max(g.items, function (e) { return e.ms; }), rows: max(g.items, function (e) { return e.rows; }),
      waited: g.items.filter(function (e) { return e.behind; }).length,
    };
  }).sort(function (a, b) { return b.max - a.max; });
  if (opGroups.length) L.push("Storage (store @ where op: n, max[, rows][, waited]): " + opGroups.slice(0, 12).map(function (g) {
    return g.store + " @ " + (g.ctx || "dashboard") + " " + g.op + ": " + g.count + ", " + g.max + (g.rows != null ? ", " + g.rows + " rows" : "") + (g.waited ? ", waited " + g.waited : "");
  }).join("; "));
  // "~" = credited from the tool step just before it (not a tile launch).
  if (aiGroups.length) L.push("Gemini (tool[~ inferred]: n, avg, max, first words; models): " + aiGroups.map(function (g) {
    return (g.id || "background") + (g.inferred ? "~" : "") + ": " + g.count + ", " + g.avg + ", " + g.max + (g.first != null ? ", " + g.first : "") + "; " + g.models.join("/");
  }).join(" | "));
  if (retries.length || aiFailed.length) L.push("Gemini retries " + retries.length + " (waited " + sum(retries, function (e) { return e.ms; }) + "ms) · failures " + aiFailed.length);
  if (freezeGroups.length) L.push("Freezes (where: n, max ms): " + freezeGroups.map(function (g) { return (g.ctx || "dashboard") + ": " + g.count + ", " + g.max; }).join("; "));
  if (sys) {
    var M = function (c) { return c == null ? "?" : (c / 1048576).toFixed(1) + "MB"; };
    L.push("System: heap " + (sys.heap ? M(sys.heap.used) + " of " + M(sys.heap.limit) : "n/a") +
      (code ? "; tool code loaded " + M(code.loaded) + " (" + code.loadedN + "), not opened " + M(code.waiting) + " (" + code.waitingN + ")" +
        (code.biggestWaiting.length ? " [" + code.biggestWaiting.map(function (b) { return b.id + " " + M(b.chars); }).join(", ") + "]" : "") : "") +
      (sys.storage ? "; saved data " + M(sys.storage.used) + " of " + M(sys.storage.quota) : "") +
      (sys.domNodes != null ? "; DOM nodes " + sys.domNodes : "") +
      "; Word quick trips " + (trips ? trips.join("/") + "ms" : "n/a") +
      "; freeze recorder " + sys.freezes);
  }
  if (issues.length) {
    L.push("Issues:");
    issues.forEach(function (i, k) { L.push((k + 1) + ". [" + (i.who === "eli" ? "ELI" : i.who === "word" ? "Word" : "Gemini") + "] " + i.text); });
  }

  return {
    full: full, empty: empty, verdict: verdict, cards: cards,
    issues: issues.slice(0, 3), moreIssues: Math.max(0, issues.length - 3),
    since: full ? tm.since : null, count: full ? entries.length : 0,
    copyText: L.join("\n"),
    overview: verdict.title,
    provenance: {
      kernelVersion: String(input.kernelVersion || ""), toolVersion: String(input.toolVersion || ""),
      docHash: "", timestamp: input.now || 0,
    },
  };
}

// selectionTestAnalyze(raw) — scores the selection signals test (init's
// _selectionTestRun). raw.truth: selection-text changes seen by polling,
// each { lo, hi, kind } (it happened between lo and hi, performance.now ms).
// raw.signals.{word,office,eli}: { state: ok|missing|failed, times }.
// A change counts as caught when a signal arrived after it, within a
// second, and before the next change began — so a signal for the next
// change can't cover a missed one. Each signal counts once. Counts only,
// never selection text.

engine.selectionTestAnalyze:
function selectionTestAnalyze(raw) {
  raw = raw || {};
  var LATENCY_MS = 1000;
  var truth = raw.truth || [];
  var sig = raw.signals || {};
  var PLURAL = { select: "selections", deselect: "deselects", change: "switches between selections" };
  var SINGULAR = { select: "selection", deselect: "deselect", change: "switch between selections" };
  var kinds = { select: 0, deselect: 0, change: 0 };
  truth.forEach(function (c) { kinds[c.kind] = (kinds[c.kind] || 0) + 1; });
  function commas(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ","); }
  function kindList(counts) {
    var parts = [];
    ["deselect", "select", "change"].forEach(function (k) {
      if (counts[k]) parts.push(counts[k] + " " + (counts[k] === 1 ? SINGULAR[k] : PLURAL[k]));
    });
    return parts.length <= 1 ? (parts[0] || "") : parts.slice(0, -1).join(", ") + " and " + parts[parts.length - 1];
  }
  function median(a) {
    a = (a || []).slice().sort(function (x, y) { return x - y; });
    return a.length ? a[Math.floor(a.length / 2)] : null;
  }
  // raw.kernelSel (kernels from 2026-10-17): ELI reads the selection on
  // Office's signal as well as Word's, so "what ELI hears" is both.
  var ks = raw.kernelSel || null;
  var DEFS = ks ? [
    { key: "word", name: "Word's signal", note: "ELI listens to this one too" },
    { key: "office", name: "Office's older signal", note: "ELI listens to this one" },
    { key: "eli", name: "What ELI hears now", note: "either signal; misses wait for the " + (ks.backupMs / 1000) + "-second backup check" },
  ] : [
    { key: "word", name: "Word's signal", note: "ELI listens to this one" },
    { key: "office", name: "Office's older signal", note: "the other one ELI could use" },
    { key: "eli", name: "What ELI hears now", note: "Word's signal after ELI's half-second smoothing" },
  ];
  function heard() {
    var o = sig.office || {}, e = sig.eli || {};
    var times = [].concat(o.state === "ok" ? o.times || [] : [], e.state === "ok" ? e.times || [] : []);
    return { state: (o.state === "ok" || e.state === "ok") ? "ok" : (e.state || "missing"), times: times };
  }
  var rows = DEFS.map(function (d) {
    var s = (ks && d.key === "eli") ? heard() : (sig[d.key] || { state: "missing", times: [] });
    var times = (s.times || []).slice().sort(function (a, b) { return a - b; });
    var caught = 0, missed = { select: 0, deselect: 0, change: 0 }, used = {};
    if (s.state === "ok") {
      truth.forEach(function (c, i) {
        // The next change began after next.lo (its last read of this state).
        var next = truth[i + 1];
        var end = next ? Math.min(c.hi + LATENCY_MS, Math.max(c.hi, next.lo)) : c.hi + LATENCY_MS;
        var hit = -1;
        for (var k = 0; k < times.length && times[k] <= end; k++) {
          if (!used[k] && times[k] > c.lo) { hit = k; break; }
        }
        if (hit >= 0) { used[hit] = true; caught++; } else missed[c.kind]++;
      });
    }
    return {
      key: d.key, name: d.name, note: d.note, state: s.state || "missing", events: times.length,
      caught: caught, total: truth.length, missed: missed,
      pct: (s.state === "ok" && truth.length) ? Math.round(caught / truth.length * 100) : null,
    };
  });
  var byKey = {};
  rows.forEach(function (r) { byKey[r.key] = r; });

  // Best candidate: most changes caught; Word on a tie (ELI already uses it).
  var cands = [byKey.word, byKey.office].filter(function (r) { return r.state === "ok"; });
  cands.sort(function (a, b) { return (b.caught - a.caught) || (a.key === "word" ? -1 : 1); });
  var best = cands[0] || null;
  var n = truth.length;
  var verdict, backupMs = null;
  if (!n) {
    verdict = { title: "No selection changes seen", detail: "Click into your document and select some text while the test runs." };
  } else if (!best) {
    verdict = { title: "Neither signal is available here", detail: "This Word doesn't offer either selection signal, so ELI has to keep checking the selection often." };
    backupMs = 600;
  } else if (best.caught === n) {
    verdict = { title: best.name + " caught every change (" + n + ")",
      detail: "ELI can rely on it and check the selection only as a backup — every 10 seconds or so, instead of every 0.6 seconds." };
    backupMs = 10000;
  } else if (best.pct >= 80) {
    verdict = { title: best.name + " caught " + best.caught + " of " + n + " changes",
      detail: "It missed " + kindList(best.missed) + ". ELI can rely on it with a backup check every 2–3 seconds." };
    backupMs = 2500;
  } else {
    verdict = { title: "Neither signal is reliable here",
      detail: "The better one, " + best.name + ", caught only " + best.caught + " of " + n + " changes (missed " + kindList(best.missed) + "). ELI should keep checking often." };
    backupMs = 600;
  }
  var eliRow = byKey.eli;
  if (ks) {
    verdict.detail += " This ELI already listens to Office's signal, with a backup check every " + (ks.backupMs / 1000) + " seconds.";
  } else if (n && eliRow.state === "ok" && eliRow.events === 0) {
    verdict.detail += " Right now ELI hears no signal at all, so it checks every 0.6 seconds the whole time.";
  }

  var tm = raw.timing || null, timing = null, timingLine = "";
  if (tm && tm.chars != null) {
    timing = { chars: tm.chars, textMs: median(tm.textMs), emptyMs: median(tm.emptyMs), empty: tm.empty || "failed" };
    timingLine = "Copying the selected text (" + commas(timing.chars) + (timing.chars === 1 ? " character" : " characters") + "): " +
      (timing.textMs == null ? "?" : timing.textMs + "ms") + " · yes/no only: " +
      (timing.empty === "ok" ? (timing.emptyMs == null ? "?" : timing.emptyMs + "ms")
        : timing.empty === "unsupported" ? "not available in this Word" : "failed");
    if (!timing.chars) timingLine += " · nothing was selected at the end — finish with Ctrl+A to see the worst case";
  }

  // End to end: when ELI's own selection checks — listened to the way
  // Home's Polish button listens — reported each change (raw.notices
  // [{ t, len }]): the first report after the change with its new length,
  // before the next change was seen. Timed from the middle of the change's
  // window.
  var notice = null, noticeLine = "";
  if (raw.notices && n) {
    var RIGHT_AWAY_MS = 700, BACKUP_OK_MS = 3500;
    notice = { fast: 0, backup: 0, late: 0, missed: 0, delays: [] };
    truth.forEach(function (c, i) {
      var limit = truth[i + 1] ? truth[i + 1].hi : Infinity, hit = null;
      for (var k = 0; k < raw.notices.length && !hit; k++) {
        var nt = raw.notices[k];
        if (nt.t > c.lo && nt.t <= limit && nt.len === c.len) hit = nt;
      }
      if (!hit) { notice.missed++; notice.delays.push(null); return; }
      var d = Math.max(0, Math.round(hit.t - (c.lo + c.hi) / 2));
      notice.delays.push(d);
      if (d <= RIGHT_AWAY_MS) notice.fast++; else if (d <= BACKUP_OK_MS) notice.backup++; else notice.late++;
    });
    var typical = median(notice.delays.filter(function (d) { return d != null; }));
    noticeLine = "How fast ELI noticed (as Polish sees it): " + notice.fast + " right away · " + notice.backup + " within 3.5s · " +
      notice.late + " later · " + notice.missed + " missed" + (typical != null ? " · typically " + (typical / 1000).toFixed(1) + "s" : "");
  }
  // Since ELI started (kernels from 2026-10-17): which kind of check found
  // each new selection during normal use — mostly Home, before this test.
  var st = ks && ks.stats, statsLine = "";
  if (st) {
    statsLine = "Before this test: Office's signal reached ELI " + st.officeEvents + (st.officeEvents === 1 ? " time" : " times") +
      ". Checks right after a signal found a new selection " + st.found.event + " of " + st.reads.event +
      " times; backup checks " + st.found.timer + " of " + st.reads.timer + ".";
  }

  var secs = Math.round((raw.ms || 0) / 1000);
  var L = ["Selection test (" + secs + "s, " + (raw.polls || 0) + " polls): " + n + " changes (select " + kinds.select +
    ", deselect " + kinds.deselect + ", change " + kinds.change + ")"];
  rows.forEach(function (r) {
    var miss = kindList(r.missed);
    L.push("  " + r.key + ": " + r.state + (r.state === "ok" ? " " + r.caught + "/" + r.total + " caught, " + r.events + " events" + (miss ? ", missed " + miss : "") : ""));
  });
  if (backupMs != null) L.push("  suggested backup check: " + backupMs + "ms");
  L.push("  kernel selection checks: " + (ks ? "Word + Office signals, backup " + ks.backupMs + "ms" +
    (ks.quietAfterSignalMs ? ", no backup for " + ks.quietAfterSignalMs + "ms after a signal" : "") + ", " + ks.listeners + " listening" : "Word signal only (older kernel)"));
  if (st) {
    L.push("  kernel stats since boot: officeEvents " + st.officeEvents + ", wordEvents " + st.wordEvents +
      ", office adds/removes/fails " + st.officeAdds + "/" + st.officeRemoves + "/" + st.officeFails +
      "; reads (found) event " + st.reads.event + " (" + st.found.event + "), timer " + st.reads.timer + " (" + st.found.timer +
      "), subscribe " + st.reads.subscribe + " (" + st.found.subscribe + "), resume " + st.reads.resume + " (" + st.found.resume +
      "), other " + st.reads.other + " (" + st.found.other + ")");
  }
  if (notice) {
    L.push("  ELI noticed: right away " + notice.fast + ", within 3.5s " + notice.backup + ", later " + notice.late + ", missed " + notice.missed);
    // Per change: signals near it (ms from the change's midpoint) and when
    // ELI noticed — shows whether a signal came before the selection settled.
    var base = raw.t0 || 0;
    L.push("  changes (start ms; signals ±ms from change; eli = noticed after):");
    truth.slice(0, 15).forEach(function (c, i) {
      var mid = (c.lo + c.hi) / 2;
      function near(times) {
        return (times || []).filter(function (x) { return x >= mid - 1500 && x <= mid + 3000; })
          .map(function (x) { var o = Math.round(x - mid); return (o >= 0 ? "+" : "") + o; }).join(",");
      }
      var d = notice.delays[i];
      L.push("    " + (i + 1) + " " + c.kind + " len" + c.len + " @" + Math.round(c.lo - base) + "-" + Math.round(c.hi - base) +
        ": office[" + near((sig.office || {}).times) + "] word[" + near((sig.word || {}).times) + "] eli" + (d == null ? " missed" : "+" + d));
    });
    if (truth.length > 15) L.push("    … " + (truth.length - 15) + " more");
  }
  if (timing) L.push("  selection read: " + timing.chars + " chars, text " + timing.textMs + "ms, isEmpty " + (timing.empty === "ok" ? timing.emptyMs + "ms" : timing.empty));

  return {
    changes: n, kinds: kinds, rows: rows, best: best ? best.key : null, backupMs: backupMs,
    verdict: verdict, timing: timing, timingLine: timingLine,
    notice: notice, noticeLine: noticeLine, statsLine: statsLine,
    copyText: L.join("\n"),
    overview: verdict.title,
    provenance: {
      kernelVersion: String(raw.kernelVersion || ""), toolVersion: String(raw.toolVersion || ""),
      docHash: "", timestamp: raw.now || 0,
    },
  };
}

// trackedCheckAnalyze(rows) — the Tracked changes check (init _tcCheck):
// per selection, do two cheap "any tracked changes?" answers agree with
// what the OOXML holds? That yes/no is all Ask ELI would rely on
// ([SEL-TC]); the dangerous miss is cheap-says-no / OOXML-says-yes — the
// chip would lose its redline colours.
//   list     (Word's tracked-changes list) vs any change in the OOXML.
//   reviewed (original vs current text differ) vs inserted/deleted/moved
//            in the OOXML — a formatting change leaves the text alone, and
//            the chip doesn't colour formatting.
// Row: { chars, empty, list, types, listMs, listError, reviewed: { differs,
// origLen, curLen }, reviewedMs, reviewedError, xml: { ins, del, move, fmt },
// xmlMs, xmlChars, xmlError }. Parts fail independently; each is compared
// only when it and the OOXML both answered.

engine.trackedCheckAnalyze:
function trackedCheckAnalyze(rows) {
  rows = rows || [];
  function median(a) {
    a = a.filter(function (x) { return x != null; }).sort(function (x, y) { return x - y; });
    return a.length ? a[Math.floor(a.length / 2)] : null;
  }
  function commas(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ","); }
  // Wording changes only: characters inside insertions/deletions when the
  // check counted them (a paragraph-mark revision carries no text), else
  // the element counts (older rows). xmlAny adds formatting changes.
  function xmlText(x) { return x.insChars != null ? x.insChars + x.delChars + x.move : x.ins + x.del + x.move; }
  function xmlAny(x) { return xmlText(x) + x.fmt; }
  function xmlDesc(x) {
    if (!x) return "?";
    var parts = [], c = x.insChars != null;
    if (x.ins) parts.push(x.ins + " inserted" + (c ? " (" + x.insChars + " chars)" : ""));
    if (x.del) parts.push(x.del + " deleted" + (c ? " (" + x.delChars + " chars)" : ""));
    if (x.move) parts.push(x.move + " moved");
    if (x.fmt) parts.push(x.fmt + " formatting");
    if (x.marks) parts.push(x.marks + " paragraph-mark");
    return parts.length ? parts.join(", ") : "none";
  }
  function plural(n, one) { return n + " " + one + (n === 1 ? "" : "s"); }
  var L0 = { compared: 0, agreed: 0, missed: 0, extra: 0 };   // list
  var R0 = { compared: 0, agreed: 0, missed: 0, extra: 0 };   // reviewed text
  var unsupported = 0, listFailed = 0, listWorked = 0, listYes = 0, xmlFailed = 0, revFailed = 0;
  var firstXmlErr = "", firstListErr = "", withText = 0, inside = 0;
  function judge(S, cheapYes, xmlYes) {
    S.compared++;
    if (cheapYes === xmlYes) { S.agreed++; return "agree"; }
    if (xmlYes) { S.missed++; return "MISSED"; }
    S.extra++; return "extra";
  }
  var out = rows.map(function (r, i) {
    var row = { n: i + 1, status: "info", text: "", sub: "" };
    if (r.empty) { row.text = "Nothing selected — select some text in Word, then Check"; return row; }
    var listTxt;
    if (r.listError) { listFailed++; firstListErr = firstListErr || r.listError; listTxt = "failed"; }
    else if (r.list == null) { unsupported++; listTxt = "n/a"; }
    else { listWorked++; if (r.list > 0) listYes++; listTxt = r.list ? String(r.list) : "none"; }
    var revTxt = r.reviewedError ? "failed" : (r.reviewed ? (r.reviewed.differs ? "changed" : "same") : "n/a");
    if (r.reviewedError) revFailed++;
    if (r.xmlError) { xmlFailed++; firstXmlErr = firstXmlErr || r.xmlError; }
    var xmlTxt = r.xmlError ? "failed (" + r.xmlError + ")" : xmlDesc(r.xml);
    var marks = [], worst = "ok", any = false;
    if (!r.xmlError && r.xml) {
      if (xmlText(r.xml) > 0) withText++;
      if (!r.listError && r.list != null) {
        any = true;
        var lj = judge(L0, r.list > 0, xmlAny(r.xml) > 0);
        if (r.list === 0 && xmlText(r.xml) > 0) inside++;   // inside a larger change — the list's blind spot
        marks.push(lj === "agree" ? "list agrees" : lj === "MISSED" ? "list MISSED" : "list says yes");
      }
      if (!r.reviewedError && r.reviewed) {
        any = true;
        var rj = judge(R0, r.reviewed.differs, xmlText(r.xml) > 0);
        marks.push(rj === "agree" ? "text agrees" : rj === "MISSED" ? "text MISSED" : "text says changed");
        worst = rj === "MISSED" ? "bad" : (rj === "extra" ? "warn" : "ok");
      } else if (any) {
        worst = marks[0] === "list MISSED" ? "bad" : (marks[0] === "list says yes" ? "warn" : "ok");
      }
    }
    row.status = any ? worst : (r.listError || r.reviewedError ? "bad" : (r.xmlError ? "warn" : "info"));
    row.text = r.chars + " chars · list: " + listTxt + " · text compare: " + revTxt + " · XML: " + xmlTxt + (marks.length ? " · " + marks.join(", ") : "");
    row.sub = [r.listMs != null ? "list " + r.listMs + "ms" : "", r.reviewedMs != null ? "text " + r.reviewedMs + "ms" : "",
      r.xmlMs != null ? "XML " + commas(r.xmlMs) + "ms" + (r.xmlError ? " to fail" : " (" + commas(r.xmlChars) + " chars)") : ""]
      .filter(Boolean).join(" · ");
    return row;
  });
  var listMed = median(rows.map(function (r) { return r.empty || r.listError || r.list == null ? null : r.listMs; }));
  var revMed = median(rows.map(function (r) { return r.empty || r.reviewedError || !r.reviewed ? null : r.reviewedMs; }));
  var xmlOkMed = median(rows.map(function (r) { return r.empty || r.xmlError ? null : r.xmlMs; }));
  var xmlFailMed = median(rows.map(function (r) { return r.xmlError ? r.xmlMs : null; }));
  var listNote = L0.compared ? " Word's list " + (L0.missed ? "missed " + L0.missed + " of " + L0.compared : "agreed " + L0.agreed + " of " + L0.compared) + "." : "";
  var verdict = null;
  if (out.length && !out.every(function (o) { return /^Nothing selected/.test(o.text); })) {
    if (R0.compared) {
      if (R0.missed) verdict = { title: "Comparing the text missed tracked changes " + R0.missed + " of " + R0.compared + " times",
        detail: "Not safe to rely on either." + listNote };
      else verdict = { title: "Comparing the text agreed " + R0.agreed + " of " + R0.compared + " times",
        detail: (withText < 3 ? "Only " + plural(withText, "selection") + " had inserted or deleted text — try more. "
          : (inside ? plural(inside, "selection") + " sat inside a larger change (the case Word's list misses) and it caught " + (inside === 1 ? "it" : "them") + ". "
            : "None sat inside a larger change yet — try one word in the middle of an inserted sentence. ")) +
          (R0.extra ? "It said changed " + R0.extra + " time" + (R0.extra === 1 ? "" : "s") + " when the XML had none — harmless, ELI would just fetch the XML. " : "") + listNote.trim() };
    } else if (L0.compared) {
      verdict = L0.missed
        ? { title: "Word's list missed tracked changes " + L0.missed + " of " + L0.compared + " times", detail: "Not safe to rely on: the chip would lose its redline colours on those selections." }
        : { title: "Word's list agreed " + L0.agreed + " of " + L0.compared + " times", detail: "The text comparison isn't available in this Word." };
    } else if (xmlFailed && listWorked) {
      verdict = { title: "Word refused the selection's XML here",
        detail: "Every XML request failed (" + firstXmlErr + "), so there's nothing to check against. Word's list answered: " + listYes + " of " + plural(listWorked, "selection") + " had tracked changes." };
    } else if (xmlFailed) {
      verdict = { title: "Word refused the XML here", detail: firstXmlErr + (firstListErr ? "; list: " + firstListErr : "") + "." };
    } else if (listFailed) {
      verdict = { title: "Word's tracked-changes list failed here", detail: firstListErr + "." };
    } else {
      verdict = { title: "This Word can't list or compare tracked changes", detail: "Ask ELI would keep fetching the XML here, as it does today." };
    }
  }
  var speed = [];
  if (listMed != null) speed.push("Word's list " + listMed + "ms");
  if (revMed != null) speed.push("text compare " + revMed + "ms");
  if (xmlOkMed != null) speed.push("fetching the XML " + commas(xmlOkMed) + "ms");
  else if (xmlFailMed != null) speed.push("the XML request took " + commas(xmlFailMed) + "ms to fail");
  var speedLine = speed.length > 1 ? "Typical: " + speed.join(" · ") : "";
  var L = ["Tracked changes check (" + rows.length + " selections): text compare agreed " + R0.agreed + "/" + R0.compared + " missed " + R0.missed + " extra " + R0.extra +
    "; list agreed " + L0.agreed + "/" + L0.compared + " missed " + L0.missed + " extra " + L0.extra +
    "; inside a larger change " + inside + "; with text changes " + withText + "; failures list " + listFailed + " text " + revFailed + " XML " + xmlFailed +
    (listMed != null ? "; median list " + listMed + "ms" : "") + (revMed != null ? ", text " + revMed + "ms" : "") +
    (xmlOkMed != null ? ", XML " + xmlOkMed + "ms" : "") + (xmlFailMed != null ? ", XML fail " + xmlFailMed + "ms" : "")];
  rows.forEach(function (r, i) {
    if (r.empty) { L.push("  " + (i + 1) + ". nothing selected"); return; }
    L.push("  " + (i + 1) + ". " + r.chars + " chars; list " +
      (r.listError ? "error: " + r.listError : (r.list == null ? "n/a" : r.list + (r.list ? " " + JSON.stringify(r.types) : ""))) +
      "; text " + (r.reviewedError ? "error: " + r.reviewedError : (r.reviewed ? (r.reviewed.differs ? "changed" : "same") + " (" + r.reviewed.origLen + "/" + r.reviewed.curLen + ")" : "n/a")) +
      "; xml " + (r.xmlError ? "error: " + r.xmlError : (r.xml ? "ins " + r.xml.ins + " del " + r.xml.del + " move " + r.xml.move + " fmt " + r.xml.fmt +
        (r.xml.insChars != null ? " insChars " + r.xml.insChars + " delChars " + r.xml.delChars + " marks " + r.xml.marks : "") + " (" + r.xmlChars + " chars)" : "?")) +
      "; " + r.listMs + "/" + r.reviewedMs + "/" + r.xmlMs + "ms");
  });
  return { rows: out, verdict: verdict, speedLine: speedLine, missed: R0.compared ? R0.missed : L0.missed, agreed: R0.compared ? R0.agreed : L0.agreed,
    compared: R0.compared || L0.compared, inside: inside, list: L0, reviewed: R0, copyText: L.join("\n") };
}

view.renderSpeedCheck:
function renderSpeedCheck(opts) {
  opts = opts || {};
  var r = opts.result || {};
  var open = opts.openCards || {};
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text != null) n.textContent = text;
    return n;
  }
  function fire(fn) { return function () { if (typeof fn === "function") fn.apply(null, arguments); }; }

  var root = el("div", "_eli3_sc_root");
  var bar = el("div", "_eli3_sc_bar");
  var back = el("button", "_eli3_sc_back", "←");
  back.type = "button";
  back.title = "Back";
  back.onclick = fire(opts.onBack);
  bar.appendChild(back);
  bar.appendChild(el("div", "_eli3_sc_title", "Speed Check"));
  root.appendChild(bar);

  var body = el("div", "_eli3_sc_body");
  root.appendChild(body);

  var v = el("div", "_eli3_sc_verdict");
  v.appendChild(el("div", "_eli3_sc_big", (r.verdict && r.verdict.title) || ""));
  v.appendChild(el("div", "_eli3_sc_small", (r.verdict && r.verdict.detail) || ""));
  body.appendChild(v);

  // Open by default: whatever the caller kept open, else the worst ELI card.
  var RANK = { bad: 3, warn: 2, ok: 1, info: 0 };
  var cards = r.cards || [];
  var anyKept = Object.keys(open).length > 0;
  if (!anyKept) {
    var worst = cards.filter(function (c) { return c.status === "bad" || c.status === "warn"; })
      .sort(function (a, b) { return RANK[b.status] - RANK[a.status]; })[0];
    if (worst) open[worst.key] = true;
  }
  var grid = el("div", "_eli3_sc_cards");
  cards.forEach(function (c) {
    var card = el("div", "_eli3_sc_card" + (open[c.key] ? " _eli3_sc_open" : ""));
    card.setAttribute("role", "button");
    card.tabIndex = 0;
    card.setAttribute("data-key", c.key);
    var top = el("div", "_eli3_sc_ctop");
    top.appendChild(el("span", "_eli3_sc_dot _eli3_sc_" + c.status));
    top.appendChild(el("span", "_eli3_sc_cname", c.name));
    card.appendChild(top);
    var val = el("div", "_eli3_sc_cval", c.value);
    if (c.unit) { val.appendChild(document.createTextNode(" ")); val.appendChild(el("small", null, c.unit)); }
    card.appendChild(val);
    card.appendChild(el("div", "_eli3_sc_cnote", c.note));
    if (open[c.key]) {
      if (c.rows && c.rows.length) {
        var bars = el("div", "_eli3_sc_bars");
        c.rows.forEach(function (row) {
          var b = el("div", "_eli3_sc_barrow");
          var nm = el("span", "_eli3_sc_nm");
          nm.appendChild(el("span", "_eli3_sc_nmt", row.name));
          if (row.sub) nm.appendChild(el("span", "_eli3_sc_nms", row.sub));
          b.appendChild(nm);
          // Rows that report a size or count (Memory) have no bar.
          var tr = el("span", "_eli3_sc_tr" + (row.noBar ? " _eli3_sc_tr_none" : ""));
          if (!row.noBar) {
            var fl = el("span", "_eli3_sc_fl _eli3_sc_fl_" + row.status);
            fl.style.width = row.pct + "%";
            tr.appendChild(fl);
          }
          b.appendChild(tr);
          b.appendChild(el("span", "_eli3_sc_ms", row.time));
          bars.appendChild(b);
        });
        card.appendChild(bars);
      }
      card.appendChild(el("div", "_eli3_sc_target", c.target + " Tap to fold."));
    }
    function toggle() {
      if (open[c.key]) delete open[c.key]; else open[c.key] = true;
      if (typeof opts.onToggle === "function") opts.onToggle(open);
    }
    card.onclick = toggle;
    card.onkeydown = function (e) { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggle(); } };
    grid.appendChild(card);
  });
  body.appendChild(grid);

  if (r.issues && r.issues.length) {
    body.appendChild(el("div", "_eli3_sc_sec", "What's slowing ELI down"));
    r.issues.forEach(function (it, i) {
      var row = el("div", "_eli3_sc_issue");
      row.appendChild(el("span", "_eli3_sc_num", String(i + 1)));
      var txt = el("div");
      txt.appendChild(el("div", "_eli3_sc_t", it.text));
      txt.appendChild(el("span", "_eli3_sc_who" + (it.who === "eli" ? " _eli3_sc_who_eli" : ""),
        it.who === "eli" ? "ELI · fixable" : it.who === "word" ? "Word · not ELI" : "Gemini · not ELI"));
      txt.appendChild(el("div", "_eli3_sc_fix", it.fix));
      row.appendChild(txt);
      body.appendChild(row);
    });
    if (r.moreIssues) {
      body.appendChild(el("div", "_eli3_sc_more", "+ " + r.moreIssues + " smaller " + (r.moreIssues === 1 ? "thing" : "things") + " — included in Copy for Claude"));
    }
  }

  // Selection signals test — init runs it; this only draws its state.
  var st = opts.selTest || null;
  body.appendChild(el("div", "_eli3_sc_sec", "Selection signals"));
  var box = el("div", "_eli3_sc_seltest");
  function boxButton(label, fn, gold) {
    var row = el("div", "_eli3_sc_acts");
    var b = el("button", "_eli3_sc_btn" + (gold ? " _eli3_sc_gold" : ""), label);
    b.type = "button";
    b.onclick = fire(fn);
    row.appendChild(b);
    return row;
  }
  if (st && (st.state === "running" || st.state === "finishing")) {
    box.appendChild(el("div", "_eli3_sc_big", st.state === "running" ? st.secondsLeft + "s left" : "Adding it up…"));
    box.appendChild(el("div", "_eli3_sc_small", st.changes + (st.changes === 1 ? " selection change" : " selection changes") + " seen so far"));
    box.appendChild(el("div", "_eli3_sc_stlead", "Click into your document, then:"));
    var steps = el("ul", "_eli3_sc_steps");
    ["Select a word, then a sentence — pause 3 seconds after each",
      "Click to deselect; move with the arrow keys",
      "Switch to another window and back, then click",
      "Finish with Ctrl+A and leave it selected"].forEach(function (s) { steps.appendChild(el("li", null, s)); });
    box.appendChild(steps);
    if (st.state === "running") box.appendChild(boxButton("Stop now", opts.onSelStop));
  } else if (st && st.result && !st.result.error) {
    var res = st.result;
    box.appendChild(el("div", "_eli3_sc_big", res.verdict.title));
    box.appendChild(el("div", "_eli3_sc_small", res.verdict.detail));
    if (res.changes) {
      var sbars = el("div", "_eli3_sc_bars");
      res.rows.forEach(function (row) {
        var b = el("div", "_eli3_sc_barrow");
        var nm = el("span", "_eli3_sc_nm");
        nm.appendChild(el("span", "_eli3_sc_nmt", row.name));
        var sub = row.state === "ok" ? row.note : (row.state === "missing" ? "not available in this Word" : "couldn't listen to it");
        nm.appendChild(el("span", "_eli3_sc_nms", sub));
        b.appendChild(nm);
        var ok = row.state === "ok";
        var tr = el("span", "_eli3_sc_tr" + (ok ? "" : " _eli3_sc_tr_none"));
        if (ok) {
          var fl = el("span", "_eli3_sc_fl _eli3_sc_fl_" + (row.pct === 100 ? "ok" : row.pct >= 80 ? "warn" : "bad"));
          fl.style.width = row.pct + "%";
          tr.appendChild(fl);
        }
        b.appendChild(tr);
