      onBack: function () { if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome(); },
      onRefresh: function () { _measure().then(_paint); },
      onToggle: function (open) { _openCards = open; _paint(); },
      onCopy: function (text) {
        var extra = (_sel && _sel.result && _sel.result.copyText) ? "\n" + _sel.result.copyText : "";
        if (_tcRows.length) extra += "\n" + analyzeTc(_tcRows).copyText;
        return eli.ui.copyText(text + extra, "Speed report");
      },
      onReset: typeof perf.clearTimings === "function"
        ? function () { perf.clearTimings(); _openCards = null; _measure().then(_paint); }
        : null,
    });
    // Swap in place on toggle/refresh so the scroll position holds.
    var prev = document.querySelector("._eli3_sc_root");
    if (prev && prev.parentNode) { prev.parentNode.replaceChild(node, prev); return; }
    var out = eli.ui.claimOutput();
    if (!out) {
      if (typeof showToast === "function") showToast("Speed Check couldn't find the panel.", "err");
      return;
    }
    out.appendChild(node);
  }
  function _show() {
    _openCards = null;
    _measure().then(_paint);
  }

  eli.register({
    tile: { app_speed_check: _show },
  });
}

jsonTools.css:
/* speed_check — light panel over the dark dashboard, navy/gold header. */

#output:has(._eli3_sc_root) { background: #f8fafc; }

._eli3_sc_root {
  flex: 1 0 auto;
  min-height: 100%;
  display: flex; flex-direction: column;
  background: #f8fafc;
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  box-sizing: border-box;
}
._eli3_sc_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
}
._eli3_sc_back {
  background: none; border: none; cursor: pointer; padding: 0 4px;
  font: 400 22px/1 Inter, sans-serif; color: #cbd5e1;
}
._eli3_sc_back:hover { color: #f2d866; }
._eli3_sc_title { flex: 1; font: 800 16px/1.2 Georgia, serif; color: #fff; letter-spacing: 0.2px; }

/* Bottom padding clears the kernel's floating zoom control. */
._eli3_sc_body { padding: 14px 14px 40px; max-width: 560px; width: 100%; margin: 0 auto; box-sizing: border-box; }

._eli3_sc_verdict { background: #fff; border: 1px solid #e2e8f0; border-left: 3px solid #c9a227; padding: 11px 12px; }
._eli3_sc_big { font: 800 15px/1.3 Georgia, serif; color: #0f172a; }
._eli3_sc_small { font: 500 11.5px/1.5 Inter, sans-serif; color: #475569; margin-top: 4px; }

._eli3_sc_cards { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 12px; }
._eli3_sc_card { background: #fff; border: 1px solid #e2e8f0; padding: 10px; cursor: pointer; text-align: left; min-width: 0; }
._eli3_sc_card:hover, ._eli3_sc_card:focus-visible { border-color: #c9a227; outline: none; }
._eli3_sc_card._eli3_sc_open { grid-column: 1 / -1; border-color: #c9a227; box-shadow: 0 2px 8px rgba(15, 23, 42, 0.06); }
._eli3_sc_ctop { display: flex; align-items: center; gap: 6px; }
._eli3_sc_dot { width: 8px; height: 8px; border-radius: 50%; flex: 0 0 auto; }
._eli3_sc_dot._eli3_sc_ok { background: #16a34a; }
._eli3_sc_dot._eli3_sc_warn { background: #d97706; }
._eli3_sc_dot._eli3_sc_bad { background: #dc2626; }
._eli3_sc_dot._eli3_sc_info { background: #94a3b8; }
._eli3_sc_cname { font: 700 10px/1 Inter, sans-serif; letter-spacing: 0.06em; text-transform: uppercase; color: #64748b; }
._eli3_sc_cval { font: 800 20px/1.1 Inter, sans-serif; color: #0f172a; margin-top: 6px; overflow-wrap: anywhere; }
._eli3_sc_cval small { font: 600 11px/1 Inter, sans-serif; color: #64748b; }
._eli3_sc_cnote { font: 500 10.5px/1.4 Inter, sans-serif; color: #475569; margin-top: 3px; }

._eli3_sc_bars { margin-top: 10px; border-top: 1px solid #eef2f6; padding-top: 8px; }
._eli3_sc_barrow { display: grid; grid-template-columns: minmax(0, 44%) 1fr minmax(40px, auto); align-items: center; gap: 8px; padding: 3px 0; }
._eli3_sc_nm { display: flex; flex-direction: column; min-width: 0; }
._eli3_sc_nmt { font: 600 11px/1.25 Inter, sans-serif; color: #334155; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
._eli3_sc_nms { font: 500 9.5px/1.25 Inter, sans-serif; color: #94a3b8; overflow-wrap: anywhere; }
._eli3_sc_tr { height: 8px; background: #eef2f6; position: relative; }
._eli3_sc_fl { position: absolute; left: 0; top: 0; bottom: 0; }
._eli3_sc_tr._eli3_sc_tr_none { background: none; }
._eli3_sc_fl_ok { background: #86efac; }
._eli3_sc_fl_warn { background: #fcd34d; }
._eli3_sc_fl_bad { background: #fca5a5; }
._eli3_sc_fl_info { background: #cbd5e1; }
._eli3_sc_ms { font: 700 11px/1 Inter, sans-serif; color: #0f172a; text-align: right; }
._eli3_sc_target { font: 500 10px/1.3 Inter, sans-serif; color: #94a3b8; margin-top: 6px; }

._eli3_sc_sec { font: 800 9px/1 Inter, sans-serif; letter-spacing: 0.13em; text-transform: uppercase; color: #8b6914; margin: 16px 0 7px; }
._eli3_sc_issue { display: flex; gap: 9px; background: #fff; border: 1px solid #e2e8f0; padding: 9px 10px; margin-bottom: 7px; }
._eli3_sc_num {
  flex: 0 0 auto; width: 18px; height: 18px;
  display: inline-flex; align-items: center; justify-content: center;
  font: 800 10px/1 Inter, sans-serif; color: #3f1d05;
  background: linear-gradient(180deg, #fbe28a, #c9a227);
}
._eli3_sc_t { font: 600 12px/1.45 Inter, sans-serif; color: #0f172a; }
._eli3_sc_who {
  display: inline-block; margin-top: 4px; padding: 3px 5px;
  font: 800 8.5px/1 Inter, sans-serif; letter-spacing: 0.08em; text-transform: uppercase;
  border: 1px solid #cbd5e1; color: #475569;
}
._eli3_sc_who_eli { border-color: #c9a227; color: #8b6914; }
._eli3_sc_fix { font: 500 10.5px/1.4 Inter, sans-serif; color: #64748b; margin-top: 3px; }
._eli3_sc_more { font: 500 10.5px/1.4 Inter, sans-serif; color: #64748b; padding: 2px 2px 0; }

._eli3_sc_seltest { background: #fff; border: 1px solid #e2e8f0; padding: 11px 12px; }
._eli3_sc_seltest ._eli3_sc_acts { margin-top: 10px; }
._eli3_sc_stlead { font: 600 11px/1.4 Inter, sans-serif; color: #334155; margin-top: 10px; }
._eli3_sc_steps { margin: 4px 0 0; padding-left: 18px; font: 500 11px/1.6 Inter, sans-serif; color: #475569; }

._eli3_sc_tcrows { margin-top: 10px; border-top: 1px solid #eef2f6; }
._eli3_sc_tcrow { display: flex; align-items: flex-start; gap: 7px; padding: 6px 0; border-bottom: 1px solid #eef2f6; }
._eli3_sc_tcrow ._eli3_sc_dot { margin-top: 4px; }
._eli3_sc_tctxt { min-width: 0; }
._eli3_sc_tct { font: 600 11px/1.4 Inter, sans-serif; color: #334155; overflow-wrap: anywhere; }
._eli3_sc_btn:disabled { opacity: 0.6; cursor: default; }

._eli3_sc_acts { display: flex; gap: 8px; margin-top: 14px; }
._eli3_sc_btn {
  flex: 1; cursor: pointer; padding: 10px 8px;
  font: 800 10.5px/1 Inter, sans-serif; letter-spacing: 0.05em; text-transform: uppercase;
  border: 1px solid #b0bcc6; color: #334155;
  background: linear-gradient(to bottom, #fbfcfd 0%, #eef2f5 48%, #dee4e9 52%, #ced6dd 100%);
}
._eli3_sc_btn:hover { border-color: #8b97a3; }
._eli3_sc_btn._eli3_sc_gold { color: #3f1d05; border-color: #8b6914; background: linear-gradient(180deg, #fbe28a, #c9a227); }
._eli3_sc_btn._eli3_sc_gold:hover { background: linear-gradient(180deg, #fde9a3, #d4ad35); }
._eli3_sc_foot { font: 500 10px/1.4 Inter, sans-serif; color: #94a3b8; text-align: center; margin-top: 10px; }
._eli3_sc_link {
  background: none; border: 0; padding: 0; cursor: pointer;
  font: inherit; color: #64748b; text-decoration: underline; text-decoration-color: #cbd5e1;
}
._eli3_sc_link:hover { color: #0f172a; }
